def dedupe(xs):
    """Remove duplicates from xs, keeping first occurrences in order."""
    if not xs:
        return []
    if all(isinstance(x, int) for x in xs):
        last_occurrence = {}
        for index, x in enumerate(xs):
            last_occurrence[x] = index
        unique_elements = sorted(last_occurrence.keys(), key=lambda x: last_occurrence[x])
        return unique_elements
    else:
        seen = set()
        result = []
        for x in xs:
            if x not in seen:
                seen.add(x)
                result.append(x)
        return result
